ALTER TABLE users ADD COLUMN IF NOT EXISTS staff_role TEXT CHECK (staff_role IN ('dispatcher','driver_reviewer','support','safety','finance','platform_admin'));
CREATE TABLE support_cases (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id BIGINT REFERENCES orders, reporter_id BIGINT NOT NULL REFERENCES users, category TEXT NOT NULL, severity TEXT NOT NULL CHECK (severity IN ('normal','urgent','safety')), status TEXT NOT NULL CHECK (status IN ('open','assigned','escalated','resolved','closed')), owner_id BIGINT REFERENCES users, escalation_reason TEXT, due_at BIGINT, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, resolved_at BIGINT);
CREATE TABLE support_case_events (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, case_id BIGINT NOT NULL REFERENCES support_cases, action TEXT NOT NULL, actor_id BIGINT NOT NULL REFERENCES users, note TEXT, created_at BIGINT NOT NULL);
CREATE TABLE staff_actions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor_id BIGINT NOT NULL REFERENCES users, action TEXT NOT NULL, target_type TEXT NOT NULL, target_id TEXT NOT NULL, purpose TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE financial_approvals (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, subject_type TEXT NOT NULL, subject_id TEXT NOT NULL, amount_minor BIGINT NOT NULL CHECK (amount_minor > 0), requested_by BIGINT NOT NULL REFERENCES users, decided_by BIGINT REFERENCES users, status TEXT NOT NULL CHECK (status IN ('pending','approved','rejected')), reason TEXT NOT NULL, created_at BIGINT NOT NULL, decided_at BIGINT);
CREATE TRIGGER support_case_events_append_only BEFORE UPDATE OR DELETE ON support_case_events FOR EACH ROW EXECUTE FUNCTION wp05_append_only();
CREATE TRIGGER staff_actions_append_only BEFORE UPDATE OR DELETE ON staff_actions FOR EACH ROW EXECUTE FUNCTION wp05_append_only();
